register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
  const resolved = this.resolveDefinition(definition);
  let staticValidator: ValidateFunction | undefined;
  if (typeof definition !== 'function') {
    try {
      staticValidator = ajv.compile(resolved.inputSchema);
    } catch (err) {
      throw new Error(
        `Failed to compile schema for tool ${resolved.name}: ${err instanceof Error ? err.message : String(err)}`
      );
    }
  }
  this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
}

/** Executes a tool by name, validating input against its schema; see specs/hal-engine-tool-input-validation/spec.md */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const definition = this.resolveDefinition(tool.definitionSource);
  let validator = tool.staticValidator;

  if (!validator) {
    validator = this.dynamicValidators.get(definition.inputSchema);
    if (!validator) {
      try {
        validator = ajv.compile(definition.inputSchema);
        this.dynamicValidators.set(definition.inputSchema, validator);
      } catch (err) {
        log.error('tool', 'dynamic schema compilation failed', {
          name,
          error: err instanceof Error ? err.message : String(err),
        });
        return {
          result: `Invalid tool definition for ${name}: schema failed to compile`,
        };
      }
    }
  }

  if (!validator(input)) {
    const errorStrings = (validator.errors ?? []).map(err => {
      if (err.keyword === 'required') {
        return `missing required property: ${err.params.missingProperty}`;
      }
      const field = err.instancePath.replace(/^\//, '').replace(/\//g, '.');
      return `property ${field} ${err.message} (expected type: ${err.params.type || 'unknown'})`;
    });

    const result = `Validation failed for tool ${name}: ${errorStrings.join('; ')}`;
    log.info('tool', 'validation failed', {name, errors: errorStrings});
    return {result};
  }

  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
  const rawResult = await tool.execute(input, context);
  const response = normalizeToolResponse(rawResult);
  log.info('tool', 'execution complete', {
    name,
    rawType: typeof rawResult,
    clientMessageCount: response.clientMessages?.length ?? 0,
    clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
    suppressAssistantResponse: response.suppressAssistantResponse ?? false,
  });
  return response;
}

