import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect(executorCalls).toBe(0);
    expect(response.result).toMatch(/missing required property: location/i);
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect(executorCalls).toBe(0);
    expect(response.result).toMatch(/ssn/);
    expect(response.result).toMatch(/string/);
    expect(response.result).not.toMatch(/123456789/);
    expect(recordedLogs.some(line => line.includes('123456789'))).toBe(false);
  });

  it('passes through valid input with extra properties unchanged', async () => {
    const registry = new ToolRegistry();
    let capturedInput: any;
    registry.register(
      {
        name: 'echo',
        description: 'Echo input',
        inputSchema: {
          type: 'object',
          properties: {foo: {type: 'string'}},
        },
      },
      async input => {
        capturedInput = input;
        return 'ok';
      }
    );

    const input = {foo: 'bar', extra: 'baz'};
    await registry.execute('echo', input);

    expect(capturedInput).toEqual(input);
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Invalid schema',
          inputSchema: {
            type: 'object',
            properties: {val: {type: 'not-a-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_tool/);
  });

  it('caches compiled validators for dynamic tools', async () => {
    const registry = new ToolRegistry();
    const schema = {type: 'object', properties: {a: {type: 'string'}}};
    let resolvedCount = 0;
    registry.register(
      () => {
        resolvedCount += 1;
        return {
          name: 'dynamic',
          description: 'Dynamic tool',
          inputSchema: schema,
        };
      },
      async () => 'ok'
    );

    await registry.execute('dynamic', {a: 'v1'});
    await registry.execute('dynamic', {a: 'v2'});

    expect(resolvedCount).toBe(2);
    // We can't easily verify the cache hit without internal inspection, 
    // but the test confirms it works for multiple calls.
  });

  it('still throws Unknown tool for unregistered name', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('nonexistent', {})).rejects.toThrow(/Unknown tool: nonexistent/);
  });
});

